 int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} GradientDrawable box(int c,float r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;} GradientDrawable stroke(int c,int border,float r){GradientDrawable d=box(Color.WHITE,r);d.setStroke(dp(1.5f),border);return d;}
