 void showMagnetic(){shell(1);body.addView(titleCard("🧲","Magnetic Tool","Test circulateur chaudière"),lp(-1,-2,0,0,0,10));rotor=new RotorView(this);body.addView(rotor,new LinearLayout.LayoutParams(-1,dp(250)));state=tv("✕  Aucune activité détectée",20,true);state.setGravity(Gravity.CENTER);state.setTextColor(RED);state.setPadding(dp(10),dp(15),dp(10),dp(15));state.setBackground(stroke(Color.WHITE,RED,16));body.addView(state,lp(-1,-2,0,0,0,10));field=tv("▂▅▇   Champ magnétique\n-- µT",20,true);field.setGravity(Gravity.CENTER);field.setPadding(dp(12),dp(12),dp(12),dp(12));field.setBackground(box(PALE,16));body.addView(field,lp(-1,-2,0,0,0,10));TextView info=tv("Approchez le haut ou l’arrière du téléphone du circulateur.\nLa roue s’anime lorsqu’une variation magnétique est détectée.",13,false);info.setPadding(dp(13),dp(13),dp(13),dp(13));info.setBackground(box(PALE,16));body.addView(info,lp(-1,-2,0,0,0,8));wave=new WaveView(this);body.addView(wave,new LinearLayout.LayoutParams(-1,dp(72)));LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);TextView so=control("🔊","Son\nactivé"),vi=control("▣","Vibration\nactivée"),re=control("▶","Relancer un test");controls.addView(so,new LinearLayout.LayoutParams(0,dp(94),1));controls.addView(vi,lp(0,dp(94),7,0,0,0));((LinearLayout.LayoutParams)vi.getLayoutParams()).weight=1;controls.addView(re,lp(0,dp(94),7,0,0,0));((LinearLayout.LayoutParams)re.getLayoutParams()).weight=1;body.addView(controls,lp(-1,-2,0,8,0,4));so.setOnClickListener(v->{sound=!sound;so.setText((sound?"🔊":"🔇")+"\nSon\n"+(sound?"activé":"coupé"));});vi.setOnClickListener(v->{vibration=!vibration;vi.setText("▣\nVibration\n"+(vibration?"activée":"coupée"));});re.setOnClickListener(v->{baseline=-1;samples.clear();lastDetected=0;state.setText("✕  Aucune activité détectée");state.setTextColor(RED);state.setBackground(stroke(Color.WHITE,RED,16));});TextView safety=tv("Aide au diagnostic uniquement : une variation magnétique ne confirme pas à elle seule le débit hydraulique du circulateur.",12,false);safety.setTextColor(MUTED);safety.setGravity(Gravity.CENTER);body.addView(safety,lp(-1,-2,6,7,6,0));baseline=-1;samples.clear();lastDetected=0;if(magnetic==null){state.setText("Magnétomètre indisponible");}else sm.registerListener(this,magnetic,SensorManager.SENSOR_DELAY_GAME);}
