 void showCounter(){shell(2);body.addView(titleCard("⏱","Top Compteur gaz","Contrôle chronométré du compteur gaz"),lp(-1,-2,0,0,0,10));final int[] dur={60},rem={60};final boolean[] run={false};final Runnable[] tick={null};LinearLayout presets=new LinearLayout(this);int[] sec={30,60,120,300};String[] names={"30 s","1 min","2 min","5 min"};TextView[] ps=new TextView[4];for(int i=0;i<4;i++){ps[i]=tv(names[i],14,true);ps[i].setGravity(Gravity.CENTER);ps[i].setBackground(box(i==1?ORANGE:PALE,12));ps[i].setTextColor(i==1?Color.WHITE:NAVY);final int ix=i;ps[i].setOnClickListener(v->{if(run[0])return;dur[0]=sec[ix];rem[0]=sec[ix];for(int j=0;j<4;j++){ps[j].setBackground(box(j==ix?ORANGE:PALE,12));ps[j].setTextColor(j==ix?Color.WHITE:NAVY);}});presets.addView(ps[i],lp(0,dp(48),i==0?0:5,0,0,0));((LinearLayout.LayoutParams)ps[i].getLayoutParams()).weight=1;}body.addView(presets,lp(-1,-2,0,0,0,12));TextView info=tv("Saisissez les deux index : l’écart s’affiche automatiquement. Le chrono reste indépendant du calcul.",14,false);info.setPadding(dp(14),dp(14),dp(14),dp(14));info.setBackground(box(PALE,14));body.addView(info,lp(-1,-2,0,0,0,12));EditText a=input("12345,678"),z=input("12345,712");body.addView(label("Index de départ",a));body.addView(label("Index de fin",z));TextView clock=tv("01:00",48,true);clock.setGravity(Gravity.CENTER);clock.setTextColor(ORANGE);body.addView(clock,lp(-1,-2,0,8,0,8));TextView start=action("▶  Lancer le test");body.addView(start,lp(-1,dp(58),0,0,0,10));LinearLayout result=new LinearLayout(this);result.setOrientation(LinearLayout.VERTICAL);result.setGravity(Gravity.CENTER);result.setPadding(dp(10),dp(13),dp(10),dp(13));result.setBackground(stroke(Color.rgb(247,255,249),GREEN,16));TextView rl=tv("ÉCART MESURÉ EN DIRECT",13,true),rv=tv("0,000 m³",32,true),lit=tv("Soit 0 litre",14,true);rv.setTextColor(GREEN);lit.setTextColor(GREEN);result.addView(rl);result.addView(rv);result.addView(lit);body.addView(result,lp(-1,-2,0,0,0,12));TextView reset=action("↻  Lancer un nouveau test");body.addView(reset,lp(-1,dp(58),0,0,0,12));TextView note=tv("ⓘ   Cet outil indique l’écart relevé au compteur sur la durée choisie. À utiliser dans le cadre de votre procédure de contrôle gaz.",13,false);note.setPadding(dp(14),dp(14),dp(14),dp(14));note.setBackground(box(PALE,14));body.addView(note);tick[0]=new Runnable(){public void run(){if(!run[0])return;rem[0]--;clock.setText(time(rem[0]));if(rem[0]<=0){run[0]=false;start.setText("✓  Test terminé");z.requestFocus();}else h.postDelayed(this,1000);}};start.setOnClickListener(v->{if(a.getText().toString().trim().isEmpty()){a.setError("Saisissez l’index de départ");return;}rem[0]=dur[0];clock.setText(time(rem[0]));run[0]=true;start.setText("●  Test en cours…");h.removeCallbacks(tick[0]);h.postDelayed(tick[0],1000);});reset.setOnClickListener(v->{run[0]=false;h.removeCallbacks(tick[0]);rem[0]=dur[0];clock.setText(time(rem[0]));a.setText("");z.setText("");rv.setText("0,000 m³");lit.setText("Soit 0 litre");start.setText("▶  Lancer le test");});TextWatcher autoCalc=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){} public void onTextChanged(CharSequence s,int st,int before,int count){calcLive(a,z,rv,lit);} public void afterTextChanged(Editable e){}};a.addTextChangedListener(autoCalc);z.addTextChangedListener(autoCalc);calcLive(a,z,rv,lit);}
 void calcLive(EditText a,EditText z,TextView rv,TextView lit){String sa=a.getText().toString().trim().replace(',','.'),sz=z.getText().toString().trim().replace(',','.');if(sa.isEmpty()||sz.isEmpty()){rv.setText("0,000 m³");lit.setText("Soit 0 litre");return;}try{double x=Double.parseDouble(sa),y=Double.parseDouble(sz);if(y<x){rv.setText("—");lit.setText("Index final inférieur au départ");lit.setTextColor(RED);return;}double d=y-x;rv.setText(String.format(Locale.FRANCE,"%.3f m³",d));lit.setText(String.format(Locale.FRANCE,"Soit %.0f litres",d*1000));lit.setTextColor(GREEN);}catch(Exception e){rv.setText("—");lit.setText("Valeurs incorrectes");lit.setTextColor(RED);}}
 void calc(EditText a,EditText z,TextView rv,TextView lit){try{double x=Double.parseDouble(a.getText().toString().replace(',','.')),y=Double.parseDouble(z.getText().toString().replace(',','.'));if(y<x){z.setError("Index final inférieur à l’index de départ");return;}double d=y-x;rv.setText(String.format(Locale.FRANCE,"%.3f m³",d));lit.setText(String.format(Locale.FRANCE,"Soit %.0f litres",d*1000));}catch(Exception e){z.setError("Saisissez les deux index");}}
 LinearLayout label(String s,EditText e){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);TextView l=tv(s,14,true);x.addView(l);x.addView(e,lp(-1,dp(54),0,5,0,10));return x;} EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(17);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setPadding(dp(13),0,dp(13),0);e.setBackground(stroke(Color.WHITE,Color.rgb(190,210,226),11));return e;} TextView action(String s){TextView t=tv(s,16,true);t.setGravity(Gravity.CENTER);t.setTextColor(Color.WHITE);t.setBackground(box(ORANGE,13));return t;}
 void showSettings(){shell(3);body.addView(titleCard("⚙","Paramètres","Réglages de Chauff’Doc"),lp(-1,-2,0,0,0,14));body.addView(setting("🔊","Sons","Activer / Désactiver les sons",sound,()->{sound=!sound;showSettings();}));body.addView(setting("▣","Vibrations","Activer / Désactiver les vibrations",vibration,()->{vibration=!vibration;showSettings();}));body.addView(setting("▰","Unités","m³ et litres",true,null));body.addView(setting("ⓘ","À propos","Chauff’Doc v1.1 • Design V3",true,null));TextView slogan=tv("Chauff’Doc\nDes outils simples pour un diagnostic efficace !",21,true);slogan.setGravity(Gravity.CENTER);slogan.setTextColor(NAVY);body.addView(slogan,lp(-1,-2,0,30,0,0));}
 View setting(String icon,String title,String sub,boolean on,Runnable r){LinearLayout c=new LinearLayout(this);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(dp(14),dp(10),dp(14),dp(10));c.setBackground(box(PALE,14));TextView ic=tv(icon,25,true);c.addView(ic,lp(dp(45),-2,0,0,6,0));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.addView(tv(title,16,true));TextView s=tv(sub,12,false);s.setTextColor(MUTED);tx.addView(s);c.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView sw=tv(on?"●":"○",28,true);sw.setTextColor(on?ORANGE:MUTED);c.addView(sw);if(r!=null)c.setOnClickListener(v->r.run());c.setLayoutParams(lp(-1,dp(72),0,0,0,10));return c;}
 @Override public void onSensorChanged(SensorEvent e){if(e.sensor.getType()!=Sensor.TYPE_MAGNETIC_FIELD||rotor==null)return;float x=e.values[0],y=e.values[1],z=e.values[2],mag=(float)Math.sqrt(x*x+y*y+z*z);field.setText(String.format(Locale.FRANCE,"▂▅▇   Champ magnétique\n%.0f µT",mag));samples.addLast(mag);if(samples.size()>28)samples.removeFirst();if(baseline<0)baseline=mag;else baseline=baseline*.985f+mag*.015f;float mean=0;for(float f:samples)mean+=f;mean/=Math.max(1,samples.size());float dev=0;for(float f:samples)dev+=Math.abs(f-mean);dev/=Math.max(1,samples.size());if(wave!=null){wave.value=Math.min(1f,dev/10f);wave.invalidate();}boolean active=samples.size()>12&&(dev>2.2f||Math.abs(mag-baseline)>8f);long now=System.currentTimeMillis();if(active){lastDetected=now;rotor.running=true;rotor.invalidate();state.setText("✓  Activité magnétique détectée");state.setTextColor(GREEN);state.setBackground(stroke(Color.WHITE,GREEN,16));if(now-lastFeedback>1800){lastFeedback=now;if(sound)tone.startTone(ToneGenerator.TONE_PROP_BEEP,90);if(vibration){Vibrator vb=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(Build.VERSION.SDK_INT>=26)vb.vibrate(VibrationEffect.createOneShot(80,VibrationEffect.DEFAULT_AMPLITUDE));else vb.vibrate(80);}}}else if(now-lastDetected>1200){rotor.running=false;rotor.invalidate();state.setText("✕  Aucune activité détectée");state.setTextColor(RED);state.setBackground(stroke(Color.WHITE,RED,16));}}
 @Override public void onAccuracyChanged(Sensor s,int a){} String time(int s){return String.format(Locale.FRANCE,"%02d:%02d",s/60,s%60);} @Override protected void onPause(){super.onPause();if(sm!=null)sm.unregisterListener(this);} @Override protected void onResume(){super.onResume();if(magnetic!=null&&rotor!=null)sm.registerListener(this,magnetic,SensorManager.SENSOR_DELAY_GAME);}
 class BrandHeader extends View{Paint p=new Paint(1);BrandHeader(Context c){super(c);setBackgroundColor(NAVY);}protected void onDraw(Canvas c){super.onDraw(c);float h=getHeight(),x=dp(52),cy=h*.50f;p.setColor(ORANGE);Path f=new Path();f.moveTo(x,cy-dp(33));f.cubicTo(x-dp(28),cy-dp(5),x-dp(23),cy+dp(27),x,cy+dp(32));f.cubicTo(x+dp(29),cy+dp(22),x+dp(27),cy-dp(5),x,cy-dp(33));c.drawPath(f,p);p.setColor(Color.WHITE);Path w=new Path();w.moveTo(x,cy-dp(14));w.cubicTo(x-dp(13),cy+dp(1),x-dp(10),cy+dp(20),x,cy+dp(24));w.cubicTo(x+dp(14),cy+dp(17),x+dp(13),cy+dp(2),x,cy-dp(14));c.drawPath(w,p);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(31));p.setColor(Color.WHITE);c.drawText("Chauff’",dp(83),cy+dp(6),p);float tw=p.measureText("Chauff’");p.setColor(ORANGE);c.drawText("Doc",dp(83)+tw,cy+dp(6),p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(dp(8));p.setColor(Color.WHITE);c.drawText("VOTRE ALLIÉ POUR DES CHAUDIÈRES EN BONNE SANTÉ",dp(84),cy+dp(24),p);}}
 static class RotorView extends View{Paint p=new Paint(1);boolean running;float angle;RotorView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.43f;p.setColor(NAVY2);c.drawCircle(cx,cy,r,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(2,r*.025f));p.setColor(Color.rgb(68,88,108));c.drawCircle(cx,cy,r*.87f,p);p.setStyle(Paint.Style.FILL);c.save();c.rotate(angle,cx,cy);p.setColor(running?ORANGE:Color.rgb(66,81,97));for(int i=0;i<5;i++){c.save();c.rotate(i*72,cx,cy);RectF q=new RectF(cx-r*.10f,cy-r*.72f,cx+r*.34f,cy-r*.08f);c.drawOval(q,p);c.restore();}c.restore();p.setColor(Color.LTGRAY);c.drawCircle(cx,cy,r*.14f,p);p.setColor(NAVY);c.drawCircle(cx,cy,r*.055f,p);if(running){angle+=11;postInvalidateDelayed(32);}}}
 static class WaveView extends View{Paint p=new Paint(1);float value=.05f;Random rnd=new Random(3);WaveView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);p.setColor(ORANGE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);Path path=new Path();float mid=getHeight()/2f;path.moveTo(0,mid);for(int x=0;x<getWidth();x+=10){float amp=(float)Math.sin(x*.13)*getHeight()*.38f*value+(rnd.nextFloat()-.5f)*getHeight()*.25f*value;path.lineTo(x,mid+amp);}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
